  const [path, setPath] = useState("");
  const [source, setSource] = useState("");
  const [data, setData] = useState([]);

  switch (source) {
    case "fakestoreapi":
      useEffect =
        (() => {
          if (path !== "") {
            fetch(`https://fakestoreapi.com/{path}`)
              .then((res) => res.json())
              .then((data) => setData(data));
          }
        },
        [path]);
      break;
    case "dummyjson":
      useEffect = (()=>{

      }, [path])
      break;
    case "jsonplaceholder":
      break;
    default:
      break;
  }

  return (
    <div>
      <Nav setPath={setPath} setSource={setSource} />
      <Body />
    </div>
  );
}

export default App;
